// 8-bit keyboard scancodes for keys 0 through 9.
localparam [7:0] KEY_0 = 8'h45;
localparam [7:0] KEY_1 = 8'h16;
localparam [7:0] KEY_2 = 8'h1e;
localparam [7:0] KEY_3 = 8'h26;
localparam [7:0] KEY_4 = 8'h25;
localparam [7:0] KEY_5 = 8'h2e;
localparam [7:0] KEY_6 = 8'h36;
localparam [7:0] KEY_7 = 8'h3d;
localparam [7:0] KEY_8 = 8'h3e;
localparam [7:0] KEY_9 = 8'h46;

module TopModule(input [7:0] code, output [3:0] out, output valid);
    reg [3:0] out_reg;
    reg valid_reg;
    always @(*) begin
        case (code)
            KEY_0: begin out_reg = 4'd0; valid_reg = 1; end
            KEY_1: begin out_reg = 4'd1; valid_reg = 1; end
            KEY_2: begin out_reg = 4'd2; valid_reg = 1; end
            KEY_3: begin out_reg = 4'd3; valid_reg = 1; end
            KEY_4: begin out_reg = 4'd4; valid_reg = 1; end
            KEY_5: begin out_reg = 4'd5; valid_reg = 1; end
            KEY_6: begin out_reg = 4'd6; valid_reg = 1; end
            KEY_7: begin out_reg = 4'd7; valid_reg = 1; end
            KEY_8: begin out_reg = 4'd8; valid_reg = 1; end
            KEY_9: begin out_reg = 4'd9; valid_reg = 1; end
            default: begin out_reg = 4'd0; valid_reg = 0; end
        endcase
    end
    assign out = out_reg;
    assign valid = valid_reg;
endmodule

// This is a one-hot-to-binary decoder, turning a one-hot 8-bit signal into a
// 4-bit index (range 0-9). The "valid" output is high iff one of the
// cases (0-9) was recognized.
module TopModule (
    input  [7:0] code,
    output [3:0] out,
    output       valid
);
    reg [3:0] out_reg;
    reg       valid_reg;
    always @(*) begin
        case (code)
            8'h45: {valid_reg, out_reg} = {1'b1, 4'd0};
            8'h16: {valid_reg, out_reg} = {1'b1, 4'd1};
            8'h1E: {valid_reg, out_reg} = {1'b1, 4'd2};
            8'h26: {valid_reg, out_reg} = {1'b1, 4'd3};
            8'h25: {valid_reg, out_reg} = {1'b1, 4'd4};
            8'h2E: {valid_reg, out_reg} = {1'b1, 4'd5};
            8'h36: {valid_reg, out_reg} = {1'b1, 4'd6};
            8'h3D: {valid_reg, out_reg} = {1'b1, 4'd7};
            8'h3E: {valid_reg, out_reg} = {1'b1, 4'd8};
            8'h46: {valid_reg, out_reg} = {1'b1, 4'd9};
            default: {valid_reg, out_reg} = {1'b0, 4'd0};
        endcase
    end
    assign valid = valid_reg;
    assign out = out_reg;
endmodule

