// Single-cycle FSM recognizing a set of keyboard scancodes
module TopModule(input [7:0] code, output reg [3:0] out, output reg valid);
  reg [3:0] state;
  always @(*) begin
    case (code)
      8'h45: state = 0;
      8'h16: state = 1;
      8'h1e: state = 2;
      8'h26: state = 3;
      8'h25: state = 4;
      8'h2e: state = 5;
      8'h36: state = 6;
      8'h3d: state = 7;
      8'h3e: state = 8;
      8'h46: state = 9;
      default: state = 4'bxxxx;
    endcase
  end
  always @(*) begin
    out = state;
    valid = (state != 4'bxxxx);
  end
endmodule

