// One-hot-to-integer function, generated by Verilator
function integer onehot2integer(input [9:0] onehot);
    for (integer i = 0; i < 10; i = i + 1)
        if (onehot[i]) return i;
    return -1;
endfunction

module TopModule(
    input  [7:0] code,
    output reg [3:0] out,
    output reg valid
);
    reg [9:0] cases;
    always @(*) begin
        cases = 10'b0;
        case (code)
            8'h45: cases[0] = 1'b1;
            8'h16: cases[1] = 1'b1;
            8'h1E: cases[2] = 1'b1;
            8'h26: cases[3] = 1'b1;
            8'h25: cases[4] = 1'b1;
            8'h2E: cases[5] = 1'b1;
            8'h36: cases[6] = 1'b1;
            8'h3D: cases[7] = 1'b1;
            8'h3E: cases[8] = 1'b1;
            8'h46: cases[9] = 1'b1;
        endcase
        out = onehot2integer(cases);
        valid = (out != -1);
    end
endmodule

